import type { CSSProperties } from "react";

/**
 * <img> with AVIF/WebP sources generated by scripts/optimize-images.mjs, falling
 * back to the original JPEG/PNG. The <picture> wrapper is `display:contents`, so
 * it adds no box: existing `.parent img` selectors and layout stay as they were.
 *
 * `srcWidth` is the original's pixel width. When it is wider than 640px the
 * script also wrote `-640` variants, which phones and small cards pick via
 * `sizes`. Logos (`responsive={false}`) only get a same-size WebP sibling.
 */
export function Picture({
  src, alt, width, height, srcWidth, sizes, responsive = true, avif = true, loading = "lazy", fetchPriority, className, style,
}: {
  src: string; alt: string; width?: number; height?: number; srcWidth?: number; sizes?: string; responsive?: boolean; avif?: boolean;
  loading?: "lazy" | "eager"; fetchPriority?: "high" | "low" | "auto"; className?: string; style?: CSSProperties;
}) {
  const base = src.replace(/\.(jpe?g|png)$/i, "");
  const set = (ext: string) => (responsive && srcWidth && srcWidth > 640 ? `${base}-640.${ext} 640w, ${base}.${ext} ${srcWidth}w` : `${base}.${ext}`);
  const s = responsive && srcWidth && srcWidth > 640 ? sizes : undefined;
  return (
    <picture style={{ display: "contents" }}>
      {avif && <source type="image/avif" srcSet={set("avif")} sizes={s} />}
      <source type="image/webp" srcSet={set("webp")} sizes={s} />
      <img src={src} srcSet={responsive && srcWidth && srcWidth > 640 ? set("jpg").replace(`${base}.jpg ${srcWidth}w`, `${src} ${srcWidth}w`) : undefined} sizes={s} alt={alt} width={width} height={height} loading={loading} decoding={loading === "eager" ? undefined : "async"} fetchPriority={fetchPriority} className={className} style={style} />
    </picture>
  );
}
